draw() {
  ctx.save();
  ctx.translate(this.x, this.y);
  ctx.rotate(this.angle);
  ctx.beginPath();
  ctx.moveTo(15, 0);
  ctx.lineTo(-10, -8);
  ctx.lineTo(-10, 8);
  ctx.closePath();
  // Gradient for ship hull
  const grad = ctx.createLinearGradient(-15, 0, 15, 0);
  grad.addColorStop(0, '#8fbfff');
  grad.addColorStop(1, '#ffffff');
  ctx.fillStyle = grad;
  ctx.fill();
  ctx.strokeStyle = '#cce6ff';
  ctx.lineWidth = 0.5;
  ctx.stroke();
  ctx.restore();
}

